"""Small original demo assets; generated once without adding production PDF/image dependencies."""
import base64,struct,zlib
PDF=base64.b64decode('')

def portrait(index):
    """Render a compact geometric avatar/illustration as a standards-compliant RGB PNG."""
    colors=[(36,105,83),(61,100,145),(165,93,60),(112,84,150)]
    rgb=colors[index%len(colors)];size=160;raw=bytearray()
    for y in range(size):
        raw.append(0)
        for x in range(size):
            head=(x-80)**2+(y-55)**2<26**2;body=((x-80)/55)**2+((y-145)/57)**2<1
            raw.extend((241,228,206) if head else rgb if body else (228+index%4*3,239,233))
    def chunk(kind,data):return struct.pack('>I',len(data))+kind+data+struct.pack('>I',zlib.crc32(kind+data)&0xffffffff)
    return b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',struct.pack('>IIBBBBB',size,size,8,2,0,0,0))+chunk(b'IDAT',zlib.compress(bytes(raw)))+chunk(b'IEND',b'')
